		private global::Dpr.Message.MessageEnumData.InitialSoundID CheckITInitialsVowel(string str, global::Dpr.Message.MessageEnumData.ITInitialSoundID initialSound) {
			if (string.IsNullOrEmpty(str))
			{
				return global::Dpr.Message.MessageEnumData.InitialSoundID.Consonant;
			}
			if (initialSound == global::Dpr.Message.MessageEnumData.ITInitialSoundID.ConsonantOthers || str.Length < 1)
			{
				return global::Dpr.Message.MessageEnumData.InitialSoundID.Consonant;
			}
			if (initialSound == global::Dpr.Message.MessageEnumData.ITInitialSoundID.S_Consonant)
			{
				return global::Dpr.Message.MessageEnumData.InitialSoundID.Consonant2;
			}
			if (initialSound == global::Dpr.Message.MessageEnumData.ITInitialSoundID.Vowel)
			{
				return global::Dpr.Message.MessageEnumData.InitialSoundID.Vowel;
			}
			char[] chars = str.ToCharArray();
			char initial = chars[0];
			if (initial == 'A' || initial == 'a')
			{
				return global::Dpr.Message.MessageEnumData.InitialSoundID.VowelA;
			}
			if (global::Dpr.Message.MessageHelper.IsITVowelE(initial))
			{
				return global::Dpr.Message.MessageEnumData.InitialSoundID.VowelE;
			}
			switch (initial)
			{
				case 'I':
				case 'O':
				case 'U':
				case 'i':
				case 'o':
				case 'u':
					return global::Dpr.Message.MessageEnumData.InitialSoundID.Vowel;
				case 'X':
				case 'Z':
				case 'x':
				case 'z':
					return global::Dpr.Message.MessageEnumData.InitialSoundID.Consonant2;
			}
			if (chars.Length < 2)
			{
				return global::Dpr.Message.MessageEnumData.InitialSoundID.Consonant;
			}
			char second = chars[1];
			switch (initial)
			{
				case 'G':
				case 'g':
					if (second == 'N' || second == 'n')
					{
						return global::Dpr.Message.MessageEnumData.InitialSoundID.Consonant2;
					}
					break;
				case 'H':
				case 'h':
					return global::Dpr.Message.MessageEnumData.InitialSoundID.Vowel;
				case 'P':
				case 'p':
					if (second == 'N' || second == 'S' || second == 'n' || second == 's')
					{
						return global::Dpr.Message.MessageEnumData.InitialSoundID.Consonant2;
					}
					break;
				case 'S':
				case 's':
					switch (second)
					{
						case 'A':
						case 'E':
						case 'I':
						case 'O':
						case 'U':
						case 'Y':
						case 'a':
						case 'e':
						case 'i':
						case 'o':
						case 'u':
						case 'y':
						case 'È':
						case 'É':
						case 'è':
						case 'é':
							return global::Dpr.Message.MessageEnumData.InitialSoundID.Consonant;
						default:
							return global::Dpr.Message.MessageEnumData.InitialSoundID.Consonant2;
					}
				case 'T':
				case 't':
					if (second == 'S' || second == 's')
					{
						return global::Dpr.Message.MessageEnumData.InitialSoundID.Consonant2;
					}
					break;
				case 'Y':
				case 'y':
					switch (second)
					{
						case 'A':
						case 'E':
						case 'I':
						case 'O':
						case 'U':
						case 'Y':
						case 'a':
						case 'e':
						case 'i':
						case 'o':
						case 'u':
						case 'y':
						case 'È':
						case 'É':
						case 'è':
						case 'é':
							return global::Dpr.Message.MessageEnumData.InitialSoundID.Consonant2;
						default:
							return global::Dpr.Message.MessageEnumData.InitialSoundID.Consonant;
					}
			}
			return global::Dpr.Message.MessageEnumData.InitialSoundID.Consonant;
		}
