		private string GetParticleStr(int tagParameter, global::Dpr.Message.MessageTagDataModel tagDataModel) {
			int code;
			if (tagDataModel.patternId != global::Dpr.Message.MessageEnumData.TagPatternID.Word)
			{
				code = GetParticlePatternCodeByDigit(tagDataModel.count);
			}
			else
			{
				string lastStr = GetLastString(tagDataModel.strValue);
				if (string.IsNullOrEmpty(lastStr))
				{
					return string.Empty;
				}
				code = GetParticlePatternCode(lastStr);
			}
			global::Dpr.Message.MessageHelper.EmitLog(string.Format("Particle : Patchum {0} - code : {1}", (global::Dpr.Message.FormatTagGrammar.PatchumId)tagParameter, code));
			if (code < 0)
			{
				return string.Empty;
			}
			switch ((global::Dpr.Message.FormatTagGrammar.PatchumId)tagParameter)
			{
				case global::Dpr.Message.FormatTagGrammar.PatchumId.Ha:
					return code > 0 ? "은" : "는";
				case global::Dpr.Message.FormatTagGrammar.PatchumId.Wo:
					return code > 0 ? "을" : "를";
				case global::Dpr.Message.FormatTagGrammar.PatchumId.Ga:
					return code > 0 ? "이" : "가";
				case global::Dpr.Message.FormatTagGrammar.PatchumId.To:
					return code > 0 ? "과" : "와";
				case global::Dpr.Message.FormatTagGrammar.PatchumId.Ni:
					if (code > 0 && code != 8)
					{
						return "으";
					}
					return string.Empty;
				case global::Dpr.Message.FormatTagGrammar.PatchumId.Ya:
					if (code > 0)
					{
						return "이";
					}
					return string.Empty;
				case global::Dpr.Message.FormatTagGrammar.PatchumId.San:
					return code > 0 ? "아" : "야";
				default:
					return string.Empty;
			}
		}
		private string GetLastString(string str) {
			if (string.IsNullOrEmpty(str))
			{
				// stripped log (MessageHelper class-init only)
				return string.Empty;
			}
			int startIndex = str.Length - 1;
			if (startIndex == 0)
			{
				return str;
			}
			return str.Substring(startIndex, 1);
		}
		private int GetParticlePatternCode(string lastStr) {
			int result = 0;
			char[] chars = lastStr.ToCharArray();
			byte[] unicodes = global::System.Text.Encoding.Unicode.GetBytes(chars);
			if (unicodes.Length == 2)
			{
				if (!global::Dpr.Message.MessageHelper.IsDigitWordByUnicode(unicodes))
				{
					int code = (((unicodes[1] << 8) | unicodes[0]) - 0xAC00) % 588 % 28;
					return code < 0 ? 0 : code;
				}
				if (int.TryParse(lastStr, out result))
				{
					return GetParticlePatternCodeByDigit(result);
				}
				global::Dpr.Message.MessageHelper.EmitLog("Can not parse int : " + lastStr);
			}
			return -1;
		}
		private int GetParticlePatternCodeByDigit(int count) {
			int onesPlace = count % 10;
			if (onesPlace >= global::Dpr.Message.MessageDataConstants.NUM_PATCHIM_CODE_ARRAY.Length)
			{
				global::Dpr.Message.MessageHelper.EmitLog(string.Format("Patchim Digit : OnesPlace {0}", onesPlace));
				return 0;
			}
			return global::Dpr.Message.MessageDataConstants.NUM_PATCHIM_CODE_ARRAY[onesPlace];
		}
		public FormatTagGrammar() { }
		private enum PatchumId
		{
			None = 0,
			Ha = 1,
			Wo = 2,
			Ga = 3,
			To = 4,
			Ni = 5,
			Ya = 6,
			San = 7,
		}
	}
}
